contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v, address other) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (v)); require(v <= 1000000000000000000000000000000);
        require(address(this).balance >= v);
        require(other != address(this));
        require(other != address(c));

        uint beforeCaller = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeOther = c.balances(other); if (__ESBMC_reverted()) return;

        c.Deposit{value: v}(); if (__ESBMC_reverted()) return;

        uint afterCaller = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterOther = c.balances(other); if (__ESBMC_reverted()) return;

        assert(afterCaller == beforeCaller + v && afterOther == beforeOther);
    }

    receive() external payable {}
}

